def rule(id,when,action,msg,page,source=NCCP,calc=False,section=None):
 a=dict(type=action,components=['pemetrexed'],recommendation=msg)
 if calc:a['dose_calculation']='specialist_review'
 s=dict(document='NCCP00222 v5' if source==NCCP else 'EMA ALIMTA product information',url=source,page=page)
 if section:s['section']=section
 rules.append(dict(rule_id=id,when=when,action=a,source=s,explanation=msg))
rule('ECOG_OUTSIDE_USUAL_RANGE',cond('ecog','>',2),'consultant_review','NCCP eligibility is ECOG 0–2. Confirm suitability with the Consultant.',1)
rule('HYPERSENSITIVITY',cond('hypersensitivity','==',True),'contraindicated','Known pemetrexed or excipient hypersensitivity is an exclusion.',1)
rule('BREASTFEEDING',cond('breastfeeding','==',True),'contraindicated','Breastfeeding is excluded; it must be discontinued during pemetrexed treatment.',1)
rule('PREGNANCY_REVIEW',cond('pregnancy','==',True),'withhold','Withhold pending specialist assessment: pemetrexed should not be used during pregnancy unless clearly necessary after maternal and fetal risk assessment. Pregnancy is not listed as an absolute NCCP00222 exclusion.',8,SMPC,section='4.6; specialist review, not an absolute NCCP exclusion')
rule('NSCLC_HISTOLOGY_SCOPE',cond('nonsquamous_histology','==',False),'consultant_review','Both indications require NSCLC other than predominantly squamous histology. Confirm the appropriate treatment plan.',1)
rule('MAINTENANCE_PROGRESSION_SCOPE',AND(cond('indication_id','==','00222a'),cond('no_progression_after_platinum','==',False)),'consultant_review','The maintenance indication requires no progression immediately following platinum-based chemotherapy. Reconcile the indication; second-line therapy is a separate treatment decision.',1)
rule('IMMUNOTHERAPY_SEPARATE_PLAN',cond('combination_immunotherapy_planned','==',True),'consultant_review','This is standalone pemetrexed monotherapy. Pembrolizumab/pemetrexed maintenance belongs to its combination regimen with separate immune eligibility, toxicity, consent and monitoring.',1,section='Scope safeguard based on the single-agent treatment table; combination protocols are separate')
rule('INFECTION',cond('febrile_or_active_infection','==',True),'withhold','Urgently assess fever or active infection before further chemotherapy. This general safety flag alone does not establish source-confirmed febrile neutropenia or a 25% dose reduction.',2,section='Clinical safety synthesis; numeric FN reduction requires confirmed FN input')
for id,lo,hi,act,msg in [('ANC_1_TO_LT1_5',1,1.5,'consultant_review','Consult the team; if clinically well, continuation may be considered.'),('ANC_0_5_TO_LT1',.5,1,'delay','Delay pemetrexed until count recovery.')]:rule(id,AND(cond('anc_x10e9_l','>=',lo),cond('anc_x10e9_l','<',hi)),act,msg,2)
rule('ANC_LT0_5',cond('anc_x10e9_l','<',.5),'delay_then_dose_reduce','Delay until recovery, then reduce pemetrexed by 25%. Discuss dose basis and prior reductions with the Consultant.',2,calc=True)
rule('PLATELETS_75_TO_LT100',AND(cond('platelets_x10e9_l','>=',75),cond('platelets_x10e9_l','<',100)),'consultant_review','Consult the team; if clinically well, consider continuation.',2)
rule('PLATELETS_50_TO_LT75',AND(cond('platelets_x10e9_l','>=',50),cond('platelets_x10e9_l','<',75)),'delay','Delay pemetrexed until platelet recovery.',2)
rule('PLATELETS_LT50_HOLD',cond('platelets_x10e9_l','<',50),'withhold','Delay until recovery. Confirm bleeding: the source reduction is 25% for the <50 row or 50% with source-defined bleeding. Missing bleeding status is not a negative result.',2,calc=True)
rule('PLATELETS_LT50_NO_BLEED',AND(cond('platelets_x10e9_l','<',50),cond('platelet_bleeding','==',False)),'delay_then_dose_reduce','Delay until recovery, then reduce pemetrexed by 25%; confirm prior dose and the Consultant plan.',2,calc=True)
rule('PLATELETS_LT50_WITH_BLEED',cond('platelet_bleeding','==',True),'delay_then_dose_reduce','Confirmed platelets <50 with bleeding meeting ≥grade 2 under CTC v2.0 (NCI 1998): delay until recovery, then reduce pemetrexed by 50%.',2,calc=True)
rule('FEBRILE_NEUTROPENIA',cond('febrile_neutropenia','==',True),'delay_then_dose_reduce','Confirmed febrile neutropenia: delay until recovery, then reduce pemetrexed by 25%; discuss with the Consultant.',2,calc=True)
rule('PEMETREXED_CRCL_LT45',OR(cond('pemetrexed_crcl_ml_min','<',45),cond('pemetrexed_renal_band','in',['30_44','lt30'])),'contraindicated','Creatinine clearance below 45 mL/min is excluded and pemetrexed is not recommended. At ≥45 no renal adjustment is specified, but other domains remain necessary.',3)
