rule('OTHER_G3_HOLD',cond('other_nonhaem_toxicity_grade','>=',3),'withhold','Withhold other grade ≥3 toxicity until at or below pre-therapy baseline. Confirm dose-reduction history before selecting a restart or discontinuation discussion.',3,calc=True)
rule('OTHER_G3_RESTART',AND(cond('other_nonhaem_toxicity_grade','>=',3),cond('dose_reduction_count','<',2)),'withhold_then_reduce','After recovery to at or below pre-therapy baseline, resume pemetrexed at 75% of its previous dose, subject to Consultant review.',3,calc=True)
